# Copied from server.py in the pl-uic-cs418 question, along with _sample_rows() and _x_new(); keep all three in step with it
SEED_WORDS = ["acorn", "anchor", "aspen", "badger", "basil", "beacon", "birch", "bison", "bramble", "breeze", "canyon", "cedar", "comet", "fern", "jasper", "juniper"]


def _load_csv():
    path = os.path.join(os.path.dirname(__file__), "athletes.csv")
    with open(path) as f:
        reader = csv.DictReader(f)
        return [(int(row["endorsements"]), int(row["salary"])) for row in reader]


def _sha256_hex(text):
    return hashlib.sha256(text.encode()).hexdigest()


def _sample_rows(rows, seed):
    ranked = sorted(range(len(rows)), key=lambda i: _sha256_hex(f"{seed}:{i}"))
    return [rows[i] for i in sorted(ranked[:10])]


def _x_new(seed):
    return 1 + int(_sha256_hex(f"{seed}:x_new"), 16) % 6


def _cell(cell_id, cell_type, lines):
    cell = {"id": cell_id, "cell_type": cell_type, "metadata": {}, "source": "\n".join(lines)}
    if cell_type == "code":
        cell.update(outputs=[], execution_count=None)
    return cell


