def main(out_dir):
    rows = _load_csv()
    for seed in SEED_WORDS:
        folder = os.path.join(out_dir, seed)
        os.makedirs(folder, exist_ok=True)
        with open(os.path.join(folder, "athletes.csv"), "w") as f:
            f.write("\n".join(["endorsements,salary"] + [f"{e},{s}" for e, s in _sample_rows(rows, seed)]) + "\n")
        with open(os.path.join(folder, "athlete-endorsements.ipynb"), "w") as f:
            json.dump(notebook(seed), f, indent=1)
            f.write("\n")


